'use strict';
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..');
const ctx={window:{},document:{addEventListener(){}},HTMLImageElement:class{}};
vm.runInNewContext(fs.readFileSync(path.join(root,'v2-photos.js'),'utf8'),ctx);
const photo=ctx.window.RindelabPhotos,existing=require('../data/baic-photo-audit-20261123.json');
const allCoverage=require('../data/real-3cv-photo-coverage-20261123.json');
const commercial=require('../data/catalog-coverage-20261122.json');
const manifest=require('../data/baic-photo-sources-20261123.json'),curated=require('../data/baic-historical-mappings-20261123.json');
const html=fs.readFileSync(path.join(root,'index.html'),'utf8'),app=fs.readFileSync(path.join(root,'v6.js'),'utf8');
assert.equal(existing.legacyCount,39);
assert.equal(existing.legacyPhotoRows,38,'BAIC 38/39 historical images');
assert.equal(existing.groupCount,39);
assert.equal(existing.groups.filter(x=>x.withPhoto===0).length,1);
assert(existing.groups.some(x=>x.model.startsWith('Advance')&&x.withPhoto===0),'Unverified Advance model must remain without a falsely assigned image');
assert.equal(curated.count,18);
assert.equal(manifest.filter(x=>x.localSrc&&x.license).length,15);
for(const p of manifest){
 if(!p.localSrc)continue;
 assert(/^CC (?:BY|BY-SA)|^CC0/.test(p.license),'Only licensed images may be hosted '+p.key);
 assert(/^https:\/\/commons.wikimedia.org\//.test(p.source));
 assert(fs.statSync(path.resolve(root,p.localSrc)).size>9000,'Image file missing '+p.key);
}
assert.equal(photo.count,668);
assert.equal(commercial.summary.photosInLibrary,668);
assert.equal(commercial.summary.activeFamiliesTechnologies,700);
assert.equal(commercial.summary.withoutFamilyPhoto,0);
assert.equal(allCoverage.total,8394);
assert.equal(allCoverage.withPhoto+allCoverage.withoutPhoto,8394);
assert.equal(allCoverage.byBrand.Baic.withPhoto,38);
assert.equal(allCoverage.byBrand.Baic.missing,1);
assert.equal(allCoverage.withPhoto,2126);
assert.equal(allCoverage.withoutPhoto,6268);
assert(html.includes('2.126 de 8.394 fichas'),'User-visible photo coverage must not claim 100%');
assert(html.includes('scope-quick-button'),'Search result scopes must be understandable');
assert(html.includes('id="catalogScopeDetails"'),'Advanced scopes must be collapsed');
assert(!html.includes('id="catalogScopeDetails" open'),'Advanced scopes should start closed');
assert(/<option value="all" selected>Todos los vehículos/.test(html),'Default must be all models including historical');
assert(app.includes("if(all.length)performSearch({scroll:false})"),'Quick scopes should update results');
assert(app.includes("$('catalogScope').value='all';"),'Reset returns to all');
console.log('PASS BAIC historical photo audit: 38/39 cards with images (37 new fixes), honest 2.126/8.394 3CV photo coverage (25.3%), full commercial coverage separately');
